        userRole="patient"
        userName={profile?.full_name || "Patient"}
        unreadAlertsCount={unreadAlerts.length}
      />

      <main className="container mx-auto max-w-7xl px-4 sm:px-6 pt-6 space-y-6">
        {/* Welcome Banner */}
