"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import {
  Stethoscope,
  Activity,
  CheckCircle2,
  AlertTriangle,
  FileText,
  User,
  Eye,
  RefreshCw,
  Search,
  Check,
  X,
  MessageSquare,
  ShieldCheck,
  Calendar,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Navbar } from "@/components/Navbar";
import { createClient } from "@/lib/supabase/client";
import { RISK_STYLES, type RiskLevel } from "@/lib/models";
import { toast } from "sonner";
import ReactMarkdown from "react-markdown";

export default function ProviderDashboard() {
  const router = useRouter();
  const supabase = createClient();

  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<{ id: string; full_name: string | null; role: string; specialization: string | null } | null>(null);
  const [reports, setReports] = useState<any[]>([]);
  const [filter, setFilter] = useState<"all" | "pending" | "high_risk" | "validated">("all");
  const [search, setSearch] = useState("");

  // Inspection & Validation Modal
  const [selectedReport, setSelectedReport] = useState<any | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);
  const [doctorNotes, setDoctorNotes] = useState("");
  const [validating, setValidating] = useState(false);

  useEffect(() => {
    async function loadData() {
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();

        if (!user) {
          router.push("/auth");
          return;
        }

        const { data: userProfile } = await supabase.from("profiles").select("*").eq("id", user.id).single();
        if (userProfile?.role === "patient") {
          router.push("/patient");
          return;
        }
        setProfile(userProfile);

        // Fetch reports with patient profiles
        const { data: reportsData, error } = await supabase
          .from("diagnostic_reports")
          .select(`
            *,
            patient:patient_id ( id, full_name )
          `)
          .order("created_at", { ascending: false });

        if (error) throw error;
        setReports(reportsData || []);
      } catch (err) {
        console.error("Provider dashboard error:", err);
      } finally {
        setLoading(false);
      }
    }

    loadData();
  }, [router, supabase]);

  // Open Inspection Modal & fetch signed URL
  const handleInspectReport = async (report: any) => {
    setSelectedReport(report);
    setDoctorNotes(report.doctor_notes || "");
    setImageUrl(null);

    if (report.file_storage_path) {
      setImageLoading(true);
      try {
        const res = await fetch(`/api/storage/url?path=${encodeURIComponent(report.file_storage_path)}`);
        const data = await res.json();
        if (data.url) {
          setImageUrl(data.url);
        }
      } catch (err) {
        console.error("Failed to load scan image:", err);
      } finally {
        setImageLoading(false);
      }
    }
  };

  // Submit Doctor Validation
  const handleValidateReport = async () => {
    if (!selectedReport) return;
    setValidating(true);

    try {
      const res = await fetch(`/api/reports/${selectedReport.id}/validate`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ notes: doctorNotes }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Validation failed");

      toast.success("Diagnostic report clinically validated!");

      // Update local state
      setReports((prev) =>
        prev.map((r) =>
          r.id === selectedReport.id
            ? { ...r, doctor_validated: true, doctor_notes: doctorNotes, validated_at: new Date().toISOString() }
            : r
        )
      );

      setSelectedReport((prev: any) => ({ ...prev, doctor_validated: true, doctor_notes: doctorNotes }));
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to validate";
      toast.error(msg);
    } finally {
      setValidating(false);
    }
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-background">
        <div className="flex flex-col items-center gap-3">
          <RefreshCw className="h-8 w-8 animate-spin text-blue-600" />
          <p className="text-sm font-medium text-muted-foreground">Loading Clinical Workspace...</p>
        </div>
      </div>
    );
  }

  // Filtered reports
  const filteredReports = reports.filter((r) => {
    if (filter === "pending" && r.doctor_validated) return false;
    if (filter === "validated" && !r.doctor_validated) return false;
    if (filter === "high_risk" && r.risk_level !== "high" && r.risk_level !== "critical") return false;

    if (search) {
      const q = search.toLowerCase();
      const patientName = r.patient?.full_name?.toLowerCase() || "";
      const model = r.model_used.toLowerCase();
      const pred = (r.prediction_result as any)?.predicted_class?.toLowerCase() || "";
      return patientName.includes(q) || model.includes(q) || pred.includes(q);
    }

    return true;
  });

  const pendingCount = reports.filter((r) => !r.doctor_validated).length;
  const highRiskCount = reports.filter((r) => r.risk_level === "high" || r.risk_level === "critical").length;
  const validatedCount = reports.filter((r) => r.doctor_validated).length;

  return (
    <div className="min-h-screen bg-slate-50/60 pb-16">
      <Navbar
        userRole={profile?.role || "doctor"}
        userName={profile?.full_name || "Doctor"}
      />

      <main className="container mx-auto max-w-7xl px-4 sm:px-6 pt-6 space-y-6">
        {/* Header Banner */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 rounded-2xl bg-gradient-to-r from-blue-900 via-indigo-900 to-slate-900 p-6 text-white shadow-soft">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <h1 className="font-display text-2xl font-bold tracking-tight">
                {profile?.role === "hospital" || profile?.role === "clinic" ? profile.full_name : `Dr. ${profile?.full_name || "Specialist"}`}
              </h1>
              <Badge className="bg-blue-500/20 text-blue-200 border-blue-400/30 capitalize text-xs">
                {profile?.role}
              </Badge>
            </div>
            <p className="text-blue-200 text-xs sm:text-sm">
              Clinical Scan Inspection Worklist · Triage & AI Diagnostic Validation
              {profile?.specialization && ` · Department: ${profile.specialization}`}
            </p>
          </div>

          {/* Metric Stats */}
          <div className="flex items-center gap-3">
            <div className="rounded-xl bg-white/10 px-4 py-2 backdrop-blur-sm border border-white/15">
              <span className="block text-[11px] font-medium text-blue-200 uppercase tracking-wider">
                Pending Triage
              </span>
              <span className="font-display text-xl font-bold text-amber-300">{pendingCount}</span>
            </div>
            <div className="rounded-xl bg-white/10 px-4 py-2 backdrop-blur-sm border border-white/15">
              <span className="block text-[11px] font-medium text-blue-200 uppercase tracking-wider">
                Critical / High
              </span>
              <span className="font-display text-xl font-bold text-rose-400">{highRiskCount}</span>
            </div>
            <div className="rounded-xl bg-white/10 px-4 py-2 backdrop-blur-sm border border-white/15">
              <span className="block text-[11px] font-medium text-blue-200 uppercase tracking-wider">
                Validated
              </span>
              <span className="font-display text-xl font-bold text-emerald-400">{validatedCount}</span>
            </div>
          </div>
        </div>

        {/* Filter Controls & Search */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div className="flex items-center gap-2 overflow-x-auto pb-1 sm:pb-0">
            <Button
              variant={filter === "all" ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter("all")}
              className="text-xs h-8"
            >
              All Scans ({reports.length})
            </Button>
            <Button
              variant={filter === "pending" ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter("pending")}
              className="text-xs h-8"
            >
              Pending Review ({pendingCount})
            </Button>
            <Button
              variant={filter === "high_risk" ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter("high_risk")}
              className="text-xs h-8 text-rose-600 border-rose-200 hover:bg-rose-50"
            >
              High & Critical Risk ({highRiskCount})
            </Button>
            <Button
              variant={filter === "validated" ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter("validated")}
              className="text-xs h-8 text-emerald-600 border-emerald-200 hover:bg-emerald-50"
            >
              Validated ({validatedCount})
            </Button>
          </div>

          <div className="relative w-full sm:w-64">
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by patient or model..."
              className="h-8 text-xs pl-8 bg-white"
            />
            <Search className="absolute left-2.5 top-2.5 h-3.5 w-3.5 text-muted-foreground" />
          </div>
        </div>

        {/* Triage Worklist Table / Cards */}
        <Card className="border-border/80 shadow-sm">
          <CardHeader className="pb-3">
            <CardTitle className="text-base font-bold font-display">
              Incoming Diagnostic Triage Worklist
            </CardTitle>
            <CardDescription className="text-xs">
              Review scans, inspect micrographs, and approve diagnostic reports for patient records
            </CardDescription>
          </CardHeader>
          <CardContent>
            {filteredReports.length === 0 ? (
              <div className="py-12 text-center text-xs text-muted-foreground">
                No diagnostic screenings match your filter criteria.
              </div>
            ) : (
              <div className="space-y-3">
                {filteredReports.map((r) => {
                  const risk = (r.risk_level || "low") as RiskLevel;
                  const style = RISK_STYLES[risk];
                  const pred = r.prediction_result as any;

                  return (
                    <div
                      key={r.id}
                      className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 rounded-xl border border-border/70 p-4 transition-all hover:border-border hover:bg-muted/20"
                    >
                      <div className="space-y-1.5">
                        <div className="flex flex-wrap items-center gap-2">
                          <span className="font-semibold text-sm text-foreground">
                            {r.patient?.full_name || "Patient Screening"}
                          </span>
                          <Badge className={`${style.className} text-[10px] px-2 py-0 border-0 capitalize`}>
                            {risk} risk
                          </Badge>
                          <Badge variant="outline" className="text-[10px]">
                            {r.model_used}
                          </Badge>
                          {r.doctor_validated ? (
                            <Badge className="bg-emerald-50 text-emerald-700 border-emerald-200 text-[10px] flex items-center gap-1">
                              <ShieldCheck className="h-3 w-3" />
                              Validated
                            </Badge>
                          ) : (
                            <Badge variant="outline" className="text-amber-700 bg-amber-50 border-amber-200 text-[10px]">
                              Awaiting Review
                            </Badge>
                          )}
                        </div>

                        <div className="text-xs text-muted-foreground flex flex-wrap items-center gap-3">
                          <span>
                            Prediction: <strong className="text-foreground">{pred?.predicted_class || "N/A"}</strong>
                          </span>
                          <span>•</span>
                          <span>
                            Confidence: <strong className="text-foreground">{((r.confidence_score || 0) * 100).toFixed(1)}%</strong>
                          </span>
                          <span>•</span>
                          <span>Date: {new Date(r.created_at).toLocaleString()}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 self-end sm:self-center">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleInspectReport(r)}
                          className="h-8 text-xs gap-1.5 bg-white hover:bg-blue-50 hover:text-blue-600 hover:border-blue-200"
                        >
                          <Eye className="h-3.5 w-3.5" />
                          Inspect & Validate
                        </Button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </main>

      {/* Inspection & Validation Dialog */}
      {selectedReport && (
        <Dialog open={!!selectedReport} onOpenChange={(open) => !open && setSelectedReport(null)}>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle className="text-lg font-bold font-display flex items-center gap-2">
                <Stethoscope className="h-5 w-5 text-blue-600" />
                Clinical Scan Inspection & Validation
              </DialogTitle>
              <DialogDescription className="text-xs">
                Patient: {selectedReport.patient?.full_name || "Patient"} · Screening ID: {selectedReport.id.slice(0, 8)}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-6 pt-2">
              {/* Scan Micrograph Viewer */}
              <div className="rounded-xl border border-border/80 bg-slate-950 p-4 flex flex-col items-center justify-center">
                {imageLoading ? (
                  <div className="py-12 flex flex-col items-center gap-2 text-slate-400 text-xs">
                    <RefreshCw className="h-6 w-6 animate-spin text-blue-500" />
                    <span>Loading scan from secure Supabase storage...</span>
                  </div>
                ) : imageUrl ? (
                  <div className="relative max-h-72 w-full flex items-center justify-center">
                    <img
                      src={imageUrl}
                      alt="Medical scan"
                      className="max-h-72 rounded-lg object-contain border border-white/10 shadow-lg"
                    />
                  </div>
                ) : (
                  <p className="text-xs text-slate-400 py-8">Scan file not available in storage.</p>
                )}
                <span className="mt-2 text-[10px] text-slate-400">
                  Storage Path: {selectedReport.file_storage_path}
                </span>
              </div>

              {/* AI Prediction Summary */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                <div className="rounded-lg border p-2.5 bg-muted/20">
                  <span className="block text-[10px] text-muted-foreground">Model</span>
                  <span className="font-semibold text-xs text-foreground">{selectedReport.model_used}</span>
                </div>
                <div className="rounded-lg border p-2.5 bg-muted/20">
                  <span className="block text-[10px] text-muted-foreground">Prediction</span>
                  <span className="font-semibold text-xs text-foreground">
                    {(selectedReport.prediction_result as any)?.predicted_class}
                  </span>
                </div>
                <div className="rounded-lg border p-2.5 bg-muted/20">
                  <span className="block text-[10px] text-muted-foreground">Confidence</span>
                  <span className="font-semibold text-xs text-foreground">
                    {((selectedReport.confidence_score || 0) * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="rounded-lg border p-2.5 bg-muted/20">
                  <span className="block text-[10px] text-muted-foreground">Risk Level</span>
                  <Badge className={`${RISK_STYLES[selectedReport.risk_level as RiskLevel]?.className} text-[10px] border-0 capitalize mt-0.5`}>
                    {selectedReport.risk_level}
                  </Badge>
                </div>
              </div>

              {/* AI Recommendations */}
              <div className="rounded-xl border border-blue-100 bg-blue-50/40 p-4 text-xs text-foreground/90 space-y-1">
                <span className="font-semibold text-blue-900 block text-xs">AI Generated Guidance:</span>
                <div className="prose prose-xs max-w-none">
                  <ReactMarkdown>{selectedReport.ai_recommendations || "No recommendations generated."}</ReactMarkdown>
                </div>
              </div>

              {/* Doctor Clinical Notes & Validation */}
              <div className="space-y-3 border-t pt-4">
                <label className="text-xs font-semibold text-foreground flex items-center justify-between">
                  <span>Attending Physician Clinical Notes</span>
                  {selectedReport.doctor_validated && (
                    <span className="text-[10px] text-emerald-600 font-medium flex items-center gap-1">
                      <CheckCircle2 className="h-3 w-3" />
                      Clinically Validated on {new Date(selectedReport.validated_at || Date.now()).toLocaleDateString()}
                    </span>
                  )}
                </label>
                <Textarea
                  value={doctorNotes}
                  onChange={(e) => setDoctorNotes(e.target.value)}
                  placeholder="Enter clinical assessment, microscopy confirmation, recommended medication (e.g. Artemisinin-based combination therapy), or follow-up instructions..."
                  rows={3}
                  className="text-xs sm:text-sm"
                />

                <div className="flex justify-end gap-2 pt-2">
                  <Button variant="outline" size="sm" onClick={() => setSelectedReport(null)} className="text-xs">
                    Close
                  </Button>
                  <Button
                    size="sm"
                    onClick={handleValidateReport}
                    disabled={validating}
                    className="bg-emerald-600 hover:bg-emerald-700 text-white font-semibold text-xs gap-1.5"
                  >
                    {validating ? (
                      <RefreshCw className="h-3.5 w-3.5 animate-spin" />
                    ) : (
                      <Check className="h-3.5 w-3.5" />
                    )}
                    {selectedReport.doctor_validated ? "Update Clinical Validation" : "Validate Report"}
                  </Button>
                </div>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";
import { Bot, Send, X, MessageSquare, Sparkles, User, RefreshCw, AlertCircle, Stethoscope } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import ReactMarkdown from "react-markdown";

interface Message {
  role: "user" | "assistant";
  content: string;
  timestamp: string;
  doctors?: Array<{ id: string; full_name: string | null; role: string; specialization: string | null }>;
}

export function ChatAssistant() {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "assistant",
      content:
        "Hello! I am your **Diagnose Me AI Health Assistant**. I can help you understand your diagnostic reports, explain medical terms, track symptoms, or connect you with verified specialists. How can I assist you today?",
      timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    },
  ]);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) {
      scrollToBottom();
    }
  }, [messages, isOpen]);

  const handleSend = async (textToSend?: string) => {
    const text = textToSend || input;
    if (!text.trim() || loading) return;

    const userMsg: Message = {
      role: "user",
      content: text,
      timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setLoading(true);

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: text,
          history: messages.slice(-6).map((m) => ({ role: m.role, content: m.content })),
        }),
      });

      if (!res.ok) throw new Error("Failed to reach health assistant");

      const data = await res.json();
      const assistantMsg: Message = {
        role: "assistant",
        content: data.reply || "I am currently unable to process your request. Please try again shortly.",
        timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        doctors: data.recommendedDoctors,
      };

      setMessages((prev) => [...prev, assistantMsg]);
    } catch {
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content:
            "I experienced a connection issue while analyzing your inquiry. If you have an urgent medical concern, please reach out to emergency services or an in-person physician.",
          timestamp: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const quickPrompts = [
    "What does high risk in malaria mean?",
    "Explain my confidence score",
    "Find a specialist doctor",
  ];

  return (
    <>
      {/* Floating Toggle Button */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed bottom-6 right-6 z-50 flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-tr from-blue-600 to-indigo-600 text-white shadow-xl shadow-blue-500/30 transition-all duration-300 hover:scale-105 hover:shadow-blue-500/40 active:scale-95"
          aria-label="Open AI Health Assistant"
        >
          <div className="relative">
            <Bot className="h-6 w-6" />
            <span className="absolute -right-1 -top-1 flex h-3 w-3">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-emerald-400 opacity-75"></span>
              <span className="relative inline-flex h-3 w-3 rounded-full bg-emerald-500"></span>
            </span>
          </div>
        </button>
      )}

      {/* Slide-out / Floating Chat Window */}
      {isOpen && (
        <div className="fixed bottom-6 right-6 z-50 flex h-[600px] w-full max-w-[420px] flex-col rounded-2xl border border-border/80 bg-background/95 shadow-2xl backdrop-blur-lg transition-all duration-300 sm:w-[420px]">
          {/* Header */}
          <div className="flex items-center justify-between border-b border-border/60 bg-blue-600/5 px-4 py-3.5 rounded-t-2xl">
            <div className="flex items-center gap-2.5">
              <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-600 text-white shadow-sm shadow-blue-500/20">
                <Sparkles className="h-4 w-4" />
              </div>
              <div className="flex flex-col">
                <div className="flex items-center gap-1.5">
                  <span className="font-semibold text-sm text-foreground">AI Health Assistant</span>
                  <Badge variant="outline" className="border-blue-200 bg-blue-50 px-1.5 py-0 text-[10px] text-blue-700">
                    24/7 Clinical Guide
                  </Badge>
                </div>
                <span className="text-[11px] text-muted-foreground flex items-center gap-1">
                  <span className="h-1.5 w-1.5 rounded-full bg-emerald-500"></span>
                  Active & context-aware
                </span>
              </div>
            </div>
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setIsOpen(false)}
              className="h-8 w-8 rounded-full text-muted-foreground hover:text-foreground"
            >
              <X className="h-4 w-4" />
            </Button>
          </div>

          {/* Messages Body */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {messages.map((m, idx) => (
              <div
                key={idx}
                className={`flex gap-2.5 ${m.role === "user" ? "justify-end" : "justify-start"}`}
              >
                {m.role === "assistant" && (
                  <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-blue-100 text-blue-700">
                    <Bot className="h-4 w-4" />
                  </div>
                )}
                <div
                  className={`max-w-[85%] rounded-2xl px-4 py-2.5 text-xs sm:text-sm leading-relaxed shadow-sm ${
                    m.role === "user"
                      ? "bg-blue-600 text-white rounded-br-xs"
                      : "bg-muted/80 text-foreground border border-border/50 rounded-bl-xs"
                  }`}
                >
                  <div className="prose prose-sm dark:prose-invert max-w-none break-words">
                    <ReactMarkdown>{m.content}</ReactMarkdown>
                  </div>

                  {/* Recommended Doctors Card */}
                  {m.doctors && m.doctors.length > 0 && (
                    <div className="mt-3 space-y-1.5 border-t border-border/40 pt-2.5">
                      <span className="text-[11px] font-semibold text-blue-700 dark:text-blue-400 flex items-center gap-1">
                        <Stethoscope className="h-3.5 w-3.5" />
                        Available Platform Doctors:
                      </span>
                      {m.doctors.slice(0, 2).map((doc) => (
                        <div
                          key={doc.id}
                          className="flex items-center justify-between rounded-lg bg-background/80 p-2 text-xs border border-border/60"
                        >
                          <div>
                            <p className="font-medium text-foreground">Dr. {doc.full_name || "Specialist"}</p>
                            <p className="text-[10px] text-muted-foreground">{doc.specialization || "General Medicine"}</p>
                          </div>
                          <Badge variant="secondary" className="text-[10px] capitalize">
                            {doc.role}
                          </Badge>
                        </div>
                      ))}
                    </div>
                  )}

                  <span className={`block text-[10px] mt-1.5 text-right ${m.role === "user" ? "text-blue-100" : "text-muted-foreground"}`}>
                    {m.timestamp}
                  </span>
                </div>
                {m.role === "user" && (
                  <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-blue-600 text-white">
                    <User className="h-4 w-4" />
                  </div>
                )}
              </div>
            ))}

            {loading && (
              <div className="flex gap-2.5 items-center text-muted-foreground text-xs py-2">
                <div className="flex h-7 w-7 items-center justify-center rounded-full bg-blue-100 text-blue-700">
                  <RefreshCw className="h-3.5 w-3.5 animate-spin" />
                </div>
                <span>Analyzing medical guidelines...</span>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Quick Prompt Chips */}
          <div className="px-4 py-2 border-t border-border/40 flex items-center gap-1.5 overflow-x-auto no-scrollbar">
            {quickPrompts.map((q, i) => (
              <button
                key={i}
                onClick={() => handleSend(q)}
                disabled={loading}
                className="shrink-0 rounded-full border border-blue-200 bg-blue-50/50 px-2.5 py-1 text-[11px] text-blue-700 hover:bg-blue-100/70 transition-colors disabled:opacity-50"
              >
                {q}
              </button>
            ))}
          </div>

          {/* Input Footer */}
          <div className="p-3 border-t border-border/60 bg-background/80 rounded-b-2xl">
            <form
              onSubmit={(e) => {
                e.preventDefault();
                handleSend();
              }}
              className="flex items-center gap-2"
            >
              <Input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask about symptoms, reports, or care..."
                disabled={loading}
                className="h-10 text-xs sm:text-sm bg-muted/40 border-border/80 focus-visible:ring-blue-500"
              />
              <Button
                type="submit"
                size="icon"
                disabled={!input.trim() || loading}
                className="h-10 w-10 shrink-0 bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50"
              >
                <Send className="h-4 w-4" />
              </Button>
            </form>
            <p className="mt-1 text-[10px] text-center text-muted-foreground">
              Decision support only · For emergencies dial your local emergency line.
            </p>
          </div>
        </div>
      )}
    </>
  );
}

"use client";

import Link from "next/link";
import { useRouter, usePathname } from "next/navigation";
import { Activity, Bell, LogOut, ShieldAlert, User, Stethoscope } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { createClient } from "@/lib/supabase/client";

interface NavbarProps {
  userRole?: string;
  userName?: string;
  unreadAlertsCount?: number;
}

export function Navbar({ userRole, userName, unreadAlertsCount = 0 }: NavbarProps) {
  const router = useRouter();
  const pathname = usePathname();
  const supabase = createClient();

  const handleSignOut = async () => {
    await fetch("/api/auth/signout", { method: "POST" });
    await supabase.auth.signOut();
    router.push("/auth");
    router.refresh();
  };

  return (
    <header className="sticky top-0 z-40 w-full border-b border-border/60 bg-background/80 backdrop-blur-md">
      <div className="container mx-auto flex h-16 max-w-7xl items-center justify-between px-4 sm:px-6">
        {/* Brand Logo */}
        <Link href="/" className="flex items-center gap-2.5 transition-transform hover:scale-[1.02]">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-tr from-blue-600 to-indigo-600 text-white shadow-md shadow-blue-500/25">
            <Activity className="h-5 w-5" />
          </div>
          <div className="flex flex-col">
            <span className="font-display text-lg font-bold tracking-tight text-foreground">
              Diagnose<span className="text-blue-600">.me</span>
            </span>
            <span className="text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
              AI Diagnostic Platform
            </span>
          </div>
        </Link>

        {/* Navigation Links */}
        <nav className="hidden items-center gap-6 md:flex">
          {userRole === "patient" && (
            <>
              <Link
                href="/patient"
                className={`text-sm font-medium transition-colors ${
                  pathname === "/patient" ? "text-blue-600 font-semibold" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Diagnostic Studio
              </Link>
              <Link
                href="/patient/history"
                className={`text-sm font-medium transition-colors ${
                  pathname === "/patient/history" ? "text-blue-600 font-semibold" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Medical History
              </Link>
              <Link
                href="/patient/profile"
                className={`text-sm font-medium transition-colors ${
                  pathname === "/patient/profile" ? "text-blue-600 font-semibold" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Electronic Profile
              </Link>
            </>
          )}

          {userRole && userRole !== "patient" && (
            <>
              <Link
                href="/provider"
                className={`text-sm font-medium transition-colors ${
                  pathname === "/provider" ? "text-blue-600 font-semibold" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Clinical Worklist
              </Link>
              <Link
                href="/provider/verified"
                className={`text-sm font-medium transition-colors ${
                  pathname === "/provider/verified" ? "text-blue-600 font-semibold" : "text-muted-foreground hover:text-foreground"
                }`}
              >
                Validated Reports
              </Link>
            </>
          )}
        </nav>

        {/* User Status / Actions */}
        <div className="flex items-center gap-3">
          {userRole ? (
            <>
              <div className="hidden items-center gap-2 sm:flex">
                <Badge
                  variant="outline"
                  className="gap-1.5 border-blue-200 bg-blue-50/70 py-1 text-xs font-medium text-blue-700 capitalize"
                >
                  {userRole === "patient" ? (
                    <User className="h-3 w-3" />
                  ) : (
                    <Stethoscope className="h-3 w-3" />
                  )}
                  {userRole}
                </Badge>
                {userName && (
                  <span className="max-w-[130px] truncate text-xs font-medium text-muted-foreground">
                    {userName}
                  </span>
                )}
              </div>

              {unreadAlertsCount > 0 && (
                <div className="relative">
                  <Button variant="ghost" size="icon" className="relative h-9 w-9 rounded-full text-muted-foreground hover:text-foreground">
                    <Bell className="h-4 w-4" />
                    <span className="absolute right-1 top-1 flex h-4 w-4 items-center justify-center rounded-full bg-rose-500 text-[10px] font-bold text-white ring-2 ring-background">
                      {unreadAlertsCount > 9 ? "9+" : unreadAlertsCount}
                    </span>
                  </Button>
                </div>
              )}

              <Button
                variant="ghost"
                size="sm"
                onClick={handleSignOut}
                className="gap-1.5 text-xs text-muted-foreground hover:text-destructive"
              >
                <LogOut className="h-3.5 w-3.5" />
                <span className="hidden sm:inline">Sign Out</span>
              </Button>
            </>
          ) : (
            <div className="flex items-center gap-2">
              <Button variant="ghost" size="sm" asChild>
                <Link href="/auth">Sign In</Link>
              </Button>
              <Button size="sm" className="bg-blue-600 text-white shadow-sm hover:bg-blue-700" asChild>
                <Link href="/auth?tab=signup">Get Started</Link>
              </Button>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

